import { after } from 'next/server';
import { revalidateTag } from 'next/cache';
import { getCachedProducts } from '@/lib/products';

export default async function CatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Mark the cached product data as stale. Stale-while-revalidate semantics
    // mean the next request will be served from cache while fresh data is
    // fetched in the background, so admins don't need to wait.
    revalidateTag('products', 'max');

    // Defer the expensive ERP/PIM sync past the response so the admin UI
    // returns immediately. The sync runs in the background and updates the
    // underlying data source; when any catalog view is next requested, the
    // cache re-populates with the fresh result.
    after(async () => {
      await simulateErpSync();
    });
  }

  return (
    <main>
      <div>
        <h1>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </div>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

async function simulateErpSync() {
  // Placeholder for the real ERP/PIM integration. In production this would
  // pull updated pricing, inventory, and availability for all SKUs and write
  // them to the database. The next cache miss on the "products" tag will then
  // pick up the fresh rows.
  await new Promise((resolve) => setTimeout(resolve, 2000));
}

