    after(async () => {
      await simulateErpSync();
    });
  }

  return (
    <main>
      <div>
        <h1>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </div>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

async function simulateErpSync() {
  // Placeholder for the real ERP/PIM integration. In production this would
  // pull updated pricing, inventory, and availability for all SKUs and write
  // them to the database. The next cache miss on the "products" tag will then
  // pick up the fresh rows.
  await new Promise((resolve) => setTimeout(resolve, 2000));
}

